{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In situ rat brain perfusion showed that a ketoprofen-glucose glycoside crossed the BBB via transporter-mediated uptake, demonstrating that glycoside-containing molecules can achieve direct CNS entry; this supports the query's glycoside architecture under disrupted-barrier conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A glucose-bearing compound reached 3.1 nmol/g in rat brain via GLUT1-facilitated transport, providing direct evidence that sugar-containing structures can achieve meaningful brain exposure after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "NSC682769 accumulated to a brain peak of 6.22 µg/g with Cb/Cp ratios consistent with BBB penetrance in mice, showing that a polycyclic, methoxy-substituted small molecule can achieve substantial CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "N-nuciferine rapidly crossed the BBB in rats with an unbound brain Cmax of 0.16 µg/mL, demonstrating that nitrogen-containing molecules with multiple rings can achieve meaningful CNS exposure after intravenous dosing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: high-transfer experimental evidence from glycoside and polycyclic analogues demonstrates meaningful BBB/CNS entry, and the disrupted-barrier condition reduces the impact of efflux/passive-diffusion liabilities; however, no direct anthracycline/doxorubicin record is available.",
  "evidence_gaps": [
    "No direct doxorubicin or anthracycline CNS exposure record is present.",
    "The magnitude of P-glycoprotein efflux for the query under a disrupted barrier is not directly quantified.",
    "Transfer from glucose-conjugate/GLUT1-mediated evidence is mechanistically indirect for the amino-sugar anthracycline."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

